def compute(vars):
    old = vars["v1"]
    new = vars["v2"]
    value = new - old
    return {
        "value": value,
        "trace": {
            "old_ownership_interest": old,
            "new_ownership_interest": new,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
